// Takes the payment of an order through the gateway. Called by the pay button (src/ui/pay-button.js).
// A second call for the same order while the first is still running waits for the first one: the button can be
// pressed twice before the page re-renders, and a customer must never be charged twice (#43).
export function createCapture(gateway) {
  const running = new Map();
  return async function capture(order) {
    if (order.paid) return order.receipt;
    if (running.has(order.id)) return running.get(order.id);
    const p = (async () => {
      const receipt = await gateway.charge(order.id, order.total);
      order.paid = true;
      order.receipt = receipt;
      return receipt;
    })();
    running.set(order.id, p);
    try {
      return await p;
    } finally {
      running.delete(order.id);
    }
  };
}

