// The receipt line shown after a payment. Prices include 10% tax; the tax part is shown too.
export const TAX_RATE = 0.1;

export function formatReceipt(receipt) {
  const tax = Math.round((receipt.amount * TAX_RATE) / (1 + TAX_RATE));
  return `Receipt ${receipt.id}: ${receipt.amount.toLocaleString('en-US')} yen (tax ${tax.toLocaleString('en-US')} yen included)`;
}

src/ui/pay-button.js.text:
// The pay button of the checkout page, without the DOM: click() takes the payment and shows the result.
// While a payment runs, another click gets the same payment (#43).
export function createPayButton({ capture, order, show }) {
  let running = null;
  return {
    label: 'Pay',
    get disabled() {
      return running !== null;
    },
    click() {
      if (running) return running;
      running = capture(order)
        .then((receipt) => {
          show(`Paid: ${receipt.id}`);
          return receipt;
        })
        .finally(() => {
          running = null;
        });
      return running;
    },
  };
}

