import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createCapture } from '../../src/checkout/capture.js';
import { createSandboxGateway } from '../../src/gateway.js';
import { createPayButton } from '../../src/ui/pay-button.js';

// #43: pressing Pay twice before the first payment ends charged the order twice.
test('two clicks before the first payment ends charge the order once', async () => {
  const gateway = createSandboxGateway();
  const order = { id: 'o-9', total: 4500 };
  const button = createPayButton({ capture: createCapture(gateway), order, show: () => {} });
  const [first, second] = await Promise.all([button.click(), button.click()]);
  assert.equal(gateway.charges.length, 1);
  assert.equal(second.id, first.id);
});

